#include <ap_int.h>

// Embedded expected token (compile-time constant, 16 bytes).
// Default oracle value (hex): 00 11 22 33 44 55 66 77 88 99 AA BB CC DD EE FF
static const ap_uint<8> expected[16] = {
    0x00, 0x11, 0x22, 0x33,
    0x44, 0x55, 0x66, 0x77,
    0x88, 0x99, 0xAA, 0xBB,
    0xCC, 0xDD, 0xEE, 0xFF
};

ap_uint<1> check_token(const ap_uint<8> token[16]) {
    ap_uint<8> diff_acc;
    diff_acc = 0;

    // Fixed-trip loop: always processes all 16 bytes.
    for (int i = 0; i < 16; ++i) {
        ap_uint<8> d;
        d = token[i] ^ expected[i];
        diff_acc = diff_acc | d;
    }

    // Branch-free final decision.
    ap_uint<1> nonzero;
    nonzero = ap_uint<1>(diff_acc != 0);

    ap_uint<1> one;
    one = 1;

    ap_uint<1> match;
    match = one ^ nonzero;
    return match;
}
